@Test
public void testTimeNoData() throws IOException {
    int columnCount = 2;
    TimePageReader timePageReader = Mockito.mock(TimePageReader.class);
    List<ValuePageReader> valuePageReaders = new LinkedList<>();
    for (int i = 0; i < columnCount; i++) {
        valuePageReaders.add(Mockito.mock(ValuePageReader.class));
    }
    Mockito.when(timePageReader.hasNextTime()).thenReturn(false);
    Mockito.when(valuePageReaders.get(0).nextValue(Mockito.anyLong(), Mockito.anyInt())).thenReturn(null);
    Mockito.when(valuePageReaders.get(1).nextValue(Mockito.anyLong(), Mockito.anyInt())).thenReturn(null);
    LazyLoadAlignedPagePointReader reader = new LazyLoadAlignedPagePointReader(timePageReader, valuePageReaders);
    boolean hasNextValue = reader.hasNextTimeValuePair();
    Assert.assertFalse(hasNextValue);
}

